+ALTER TABLE users RENAME COLUMN email TO email_address;
+
+ALTER TABLE users ADD COLUMN email TEXT;
+
+UPDATE users
+SET email = email_address;
+
+CREATE FUNCTION sync_users_email_columns()
+RETURNS trigger
+LANGUAGE plpgsql
+AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    IF NEW.email_address IS NULL AND NEW.email IS NOT NULL THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email IS NULL AND NEW.email_address IS NOT NULL THEN
+      NEW.email := NEW.email_address;
+    ELSIF NEW.email IS NOT NULL
+        AND NEW.email_address IS NOT NULL
+        AND NEW.email <> NEW.email_address THEN
+      RAISE EXCEPTION 'users.email and users.email_address must match';
+    END IF;
+  ELSIF NEW.email IS DISTINCT FROM OLD.email
+      AND NEW.email_address IS NOT DISTINCT FROM OLD.email_address THEN
+    NEW.email_address := NEW.email;
+  ELSIF NEW.email_address IS DISTINCT FROM OLD.email_address
+      AND NEW.email IS NOT DISTINCT FROM OLD.email THEN
+    NEW.email := NEW.email_address;
+  ELSIF NEW.email IS DISTINCT FROM NEW.email_address THEN
+    RAISE EXCEPTION 'users.email and users.email_address must match';
+  END IF;
+
+  RETURN NEW;
+END;
+$$;
+
+CREATE TRIGGER sync_users_email_columns
+BEFORE INSERT OR UPDATE OF email, email_address ON users
+FOR EACH ROW
+EXECUTE FUNCTION sync_users_email_columns();

